:root {
  /* Colors */
  --color-linen-canvas: #fbf5f0;
  --color-paper: #ffffff;
  --color-sand-surface: #f3ebe4;
  --color-jet: #000000;
  --color-onyx-ink: #1d1e1c;
  --color-iron-text: #626262;
  --color-slate-tab: #666666;
  --color-pewter-nav: #6a696a;
  --color-ash-caption: #8b8b8b;
  --color-steel-outline: #999999;
  --color-dove-border: #d3d3d3;
  --color-mist-hairline: #1d1e1c1a;
  --color-ember-signal: #fa5d00;

  /* Typography — Font Families */
  --font-muoto-var: "Muoto VAR", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-besley: "Besley", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 13px;
  --leading-small: 1.2;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.5;
  --tracking-caption: -0.28px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: -0.32px;
  --text-body-lg: 18px;
  --leading-body-lg: 1;
  --tracking-body-lg: -0.54px;
  --text-subheading: 26px;
  --leading-subheading: 1.3;
  --tracking-subheading: -0.52px;
  --text-heading-sm: 30px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.9px;
  --text-heading: 50px;
  --leading-heading: 1.1;
  --tracking-heading: -2px;
  --text-display: 70px;
  --leading-display: 1.1;
  --tracking-display: -2.8px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-30: 30px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-56: 56px;
  --spacing-60: 60px;
  --spacing-80: 80px;
  --spacing-100: 100px;

  /* Layout */
  --layout-max-width: 1296px;
  --layout-section-gap: 100px;
  --layout-card-padding: 30px;
  --layout-element-gap: 24px;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 30px;
  --radius-3xl: 40px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-buttons: 30px;
  --radius-pills: 999px;
  --radius-cards: 20px;
  --radius-images: 20px;
  --radius-inputs: 16px;
  --radius-tags: 10px;
  --radius-nav: 40px;
  --radius-avatars: 50%;
  --radius-small-elements: 6px;
  --radius-sections: 40px 40px 0px 0px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.07) 0px 0px 14px 0px;
  --shadow-sm: rgba(0, 0, 0, 0.08) 0px 4px 16px 0px, rgba(0, 0, 0, 0.06) 0px 1px 3px 0px;
  --shadow-md: rgba(123, 85, 31, 0.21) 0px 4px 10px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.53) 0px 2px 16px 0px;

  /* Surfaces */
  --surface-linen-canvas: #fbf5f0;
  --surface-sand-surface: #f3ebe4;
  --surface-paper: #ffffff;
  --surface-jet: #000000;
}

